<script setup lang="ts">
type Election = { id: string; name: string; status: string }
type Contest = { id: string; code: string; title: string }
type Voter = { id: string; name: string; identifierValue: string; voterType: string; departmentCode: string | null; rights: string[] }
type Matrix = { configVersion: number; contests: Contest[]; voters: Voter[]; total: number; page: number; pageSize: number }
const { request } = useApi(); const elections = ref<Election[]>([]); const electionId = ref(''); const matrix = ref<Matrix | null>(null); const search = ref(''); const voterType = ref(''); const departmentCode = ref(''); const page = ref(1); const pageSize = 30; const loading = ref(false); const saving = ref(false); const error = ref(''); const notice = ref(''); const reason = ref('')
const changes = reactive<Record<string, boolean>>({})
const departments = ['KEP', 'KEB', 'KG', 'OP', 'OTHER']
const changeList = computed(() => Object.entries(changes).map(([key, grant]) => { const [voterId, contestId] = key.split(':'); return { voterId, contestId, grant } }))
function contestLabel(code: string) {
  const match = code.match(/^HIMA_([^_]+)_(CHAIR|VICE)$/)
  if (!match) return { group: code, role: 'Umum' }
  return { group: match[1], role: match[2] === 'CHAIR' ? 'Ketua' : 'Wakil' }
}
function path() { const q = new URLSearchParams({ page: String(page.value), pageSize: String(pageSize) }); if (search.value) q.set('search', search.value); if (voterType.value) q.set('voterType', voterType.value); if (departmentCode.value) q.set('departmentCode', departmentCode.value); return `/api/v1/admin/elections/${encodeURIComponent(electionId.value)}/rights-matrix?${q}` }
async function loadElections() { try { const result = await request<{ elections: Election[] }>('/api/v1/admin/elections'); elections.value = result.elections.filter(e => ['DRAFT', 'READY'].includes(e.status)); electionId.value = elections.value[0]?.id ?? ''; if (electionId.value) await loadMatrix() } catch (e) { error.value = apiErrorMessage(e) } }
async function loadMatrix() { if (!electionId.value) return; loading.value = true; error.value = ''; try { matrix.value = await $fetch<Matrix>(path(), { retry: 0, timeout: 15_000 }); Object.keys(changes).forEach(key => delete changes[key]) } catch (e) { error.value = apiErrorMessage(e) } finally { loading.value = false } }
function toggle(voter: Voter, contest: Contest) { const key = `${voter.id}:${contest.id}`; const original = voter.rights.includes(contest.id); const current = changes[key] ?? original; const next = !current; if (next === original) delete changes[key]; else changes[key] = next }
async function saveChanges() { if (!matrix.value || !changeList.value.length || reason.value.trim().length < 3) { error.value = 'Pilih perubahan dan isi alasan minimal 3 karakter.'; return } saving.value = true; error.value = ''; notice.value = ''; try { const result = await request<{ applied: number; reverted: number }>(`/api/v1/admin/elections/${encodeURIComponent(electionId.value)}/rights`, { electionId: electionId.value, expectConfigVersion: matrix.value.configVersion, changes: changeList.value, reason: reason.value.trim() }); notice.value = `${result.applied} perubahan hak diterapkan.`; reason.value = ''; await loadMatrix() } catch (e) { error.value = apiErrorMessage(e) } finally { saving.value = false } }
watch([electionId, search, voterType, departmentCode], () => { page.value = 1; if (electionId.value) void loadMatrix() }); watch(page, () => { if (electionId.value) void loadMatrix() }); onMounted(loadElections)
</script>
<template>
  <section class="matrix-page"><header class="page-header"><div><p class="eyebrow">PENYESUAIAN HAK</p><h1>Hak per pemilih</h1><p class="intro">Centang kontes yang boleh dipilih. Perubahan dicatat bersama alasan.</p></div><NuxtLink class="action-link" to="/admin/rights">Kembali ke kesiapan</NuxtLink></header><AppAlert v-if="error" kind="error" :message="error"/><AppAlert v-if="notice" kind="success" :message="notice"/><div class="filters"><label>Periode<select v-model="electionId"><option v-for="e in elections" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><AppInput v-model="search" label="Cari pemilih" type="search"/><label>Jenis<select v-model="voterType"><option value="">Semua</option><option value="STUDENT">Mahasiswa</option><option value="LECTURER">Dosen</option></select></label><label>Jurusan<select v-model="departmentCode"><option value="">Semua</option><option v-for="d in departments" :key="d" :value="d">{{ d }}</option></select></label></div><div v-if="loading" class="state" role="status">Memuat matriks…</div><template v-else-if="matrix"><div class="matrix-wrap" role="region" aria-label="Matriks hak pilih"><table><colgroup><col class="voter-column"><col v-for="contest in matrix.contests" :key="contest.id" class="contest-column"></colgroup><thead><tr><th>Pemilih</th><th v-for="contest in matrix.contests" :key="contest.id" :title="contest.title"><span>{{ contestLabel(contest.code).group }}</span><small>{{ contestLabel(contest.code).role }}</small></th></tr></thead><tbody><tr v-for="voter in matrix.voters" :key="voter.id"><th scope="row"><span>{{ voter.name }}</span><small>{{ voter.identifierValue }} · {{ voter.departmentCode ?? 'Tidak terikat' }}</small></th><td v-for="contest in matrix.contests" :key="contest.id"><input type="checkbox" :checked="changes[`${voter.id}:${contest.id}`] ?? voter.rights.includes(contest.id)" :aria-label="`${contest.title} untuk ${voter.name}`" @change="toggle(voter, contest)"></td></tr></tbody></table></div><div class="matrix-cards"><article v-for="voter in matrix.voters" :key="voter.id" class="voter-card"><header><strong>{{ voter.name }}</strong><small>{{ voter.identifierValue }} · {{ voter.departmentCode ?? 'Tidak terikat' }}</small></header><div class="contest-list"><label v-for="contest in matrix.contests" :key="contest.id"><input type="checkbox" :checked="changes[`${voter.id}:${contest.id}`] ?? voter.rights.includes(contest.id)" @change="toggle(voter, contest)"><span><strong>{{ contestLabel(contest.code).group }} · {{ contestLabel(contest.code).role }}</strong><small>{{ contest.title }}</small></span></label></div></article></div><AppPagination v-model:page="page" :page-size="pageSize" :total="matrix.total"/><section class="save-bar"><div><strong>{{ changeList.length }} perubahan belum disimpan</strong><p>Gunakan alasan yang dapat diperiksa panitia lain.</p></div><div class="save-controls"><input v-model="reason" aria-label="Alasan perubahan" placeholder="Alasan perubahan…" maxlength="500"><AppButton :loading="saving" :disabled="!changeList.length" @click="saveChanges">Simpan perubahan</AppButton></div></section></template><div v-else class="state">Belum ada periode DRAFT atau READY.</div></section>
</template>
<style scoped>
.matrix-page{display:grid;gap:var(--space-6);width:100%}.page-header{display:flex;justify-content:space-between;align-items:end;gap:var(--space-6);flex-wrap:wrap}.eyebrow{margin:0 0 var(--space-2);color:var(--color-primary);font-size:.75rem;font-weight:700;letter-spacing:.08em}.page-header h1{margin-bottom:var(--space-2)}.intro,.save-bar p{margin:0;color:var(--color-text-muted)}.filters{display:grid;grid-template-columns:1.5fr 2fr 1fr 1fr;gap:var(--space-4);padding:var(--card-padding);background:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-xl);box-shadow:var(--shadow-sm)}.filters label{display:grid;gap:var(--space-1);font-size:var(--text-sm);font-weight:600}.filters select,.save-controls input{min-height:2.75rem;padding:var(--space-2) var(--space-3);border:1px solid var(--color-border-strong);border-radius:var(--radius);background:var(--color-surface);font:inherit}.matrix-wrap{border:1px solid var(--color-border);border-radius:var(--radius-lg);background:var(--color-surface);box-shadow:var(--shadow-sm)}table{width:100%;table-layout:fixed;border-collapse:collapse;background:var(--color-surface);font-size:clamp(.72rem,.8vw,var(--text-sm))}.voter-column{width:clamp(11rem,18vw,16rem)}.contest-column{width:auto}th,td{padding:.75rem .35rem;border-bottom:1px solid var(--color-border);text-align:center}thead th{background:var(--color-surface-muted);position:sticky;top:0;z-index:1}thead th span,thead th small{display:block;overflow-wrap:anywhere}thead th small{margin-top:.15rem;color:var(--color-text-muted);font-size:.68rem;font-weight:600}tbody th{text-align:start;padding-inline:var(--space-3)}tbody th span,tbody th small{display:block;overflow-wrap:anywhere}tbody th small{color:var(--color-text-muted);font-weight:400}td input,.contest-list input{width:1.25rem;height:1.25rem;accent-color:var(--color-primary)}.matrix-cards{display:none}.state{padding:var(--space-8) var(--space-4);text-align:center;color:var(--color-text-muted);background:var(--color-surface);border:1px dashed var(--color-border-strong);border-radius:var(--radius-lg)}.save-bar{display:flex;justify-content:space-between;align-items:center;gap:var(--space-4);padding:var(--card-padding);background:var(--color-primary-soft);border:1px solid #9fc9b8;border-radius:var(--radius-xl)}.save-controls{display:flex;gap:var(--space-3);align-items:center}.save-controls input{min-width:18rem}.filters select:focus-visible,.save-controls input:focus-visible,td input:focus-visible,.contest-list input:focus-visible{outline:none;box-shadow:var(--focus-ring)}
@media(max-width:72rem){.matrix-wrap{display:none}.matrix-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,24rem),1fr));gap:var(--space-4)}.voter-card{min-width:0;border:1px solid var(--color-border);border-radius:var(--radius-lg);background:var(--color-surface);box-shadow:var(--shadow-sm)}.voter-card>header{display:grid;gap:.2rem;padding:var(--space-4);border-bottom:1px solid var(--color-border);background:var(--color-surface-muted)}.voter-card>header small,.contest-list small{color:var(--color-text-muted);font-weight:400}.contest-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--color-border)}.contest-list label{display:flex;align-items:center;gap:var(--space-3);min-width:0;min-height:4rem;padding:.65rem var(--space-3);background:var(--color-surface);cursor:pointer}.contest-list label span,.contest-list label strong,.contest-list label small{display:block;min-width:0}.contest-list label strong{font-size:.8rem}.contest-list label small{margin-top:.15rem;font-size:.7rem;line-height:1.35}}
@media(max-width:48rem){.filters{grid-template-columns:1fr 1fr}.filters :deep(.field):first-child{grid-column:1/-1}.save-bar,.save-controls{align-items:stretch;flex-direction:column}.save-controls input,.save-controls button{width:100%}}
@media(max-width:30rem){.filters{grid-template-columns:1fr}}
</style>
